/* ------------------------------------------------------------------
   seed_md_bom_tailgate_door_trim.sql
   MD-004 (/md/fd/bom) BOM 등록 — TAILGATE / DOOR TRIM 계열 177 품번

   출처: SEMS(SIS) ABM0990 'BOM (PARENT-CHILD RELATION)' 2026-07-02 추출본
     · 유효분 선택: EO_BEG_DATE <= '2026-09-02' <= EO_END_DATE
       → 177개 전부 EO_END_DATE='9990-12-31' 인 설변 1건씩만 걸린다 (중복 0)
     · QtyPer  ← USAGE   (BMENG=기준수량은 전 행 1)
     · UOM     ← MEINS
     · ScrapPct← AUSCH   (전 행 0.00)
     · 부품명  ← ACD0020L.PARTNM(EN), 유형 ← ACD0020.ESTI_CLASS

   1단계(직접 구성품)만 넣는다. 다단계로 펼치면 52,438 라인이 되는데,
   T/SCREW 12490-04101 같은 표준 체결부품이 SAP 에서 무관한 도어트림 22종을
   자식으로 갖는 그룹핑 레코드라 실제 BOM 이 아니기 때문이다.

   §1 MD_Uom      단위 'G' 추가 (레진 투입량이 그램 단위)
   §2 MD_Item     BOM 부품 189 건 추가 (레진·나사·클립류)
   §3 MD_BomVersion  루트 품번당 1건, 177 건 (Status=APPROVED)
   §4 MD_Bom      1단계 라인 507 건

   가드형: 이미 있으면 건너뛴다. 반복 실행 안전.
   선행: seed_md_item_tailgate_door_trim.sql (루트 177 품번이 먼저 있어야 한다)
   ------------------------------------------------------------------ */
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;

-- ── §1 MD_Uom ────────────────────────────────────────────────────────
INSERT INTO dbo.MD_Uom (UOMCode, UOMName, UOMCategory, BaseFlag, ConvFactor, DecimalPrec, Symbol, ActiveFlag, CreatedBy, CreatedTS)
SELECT 'G', 'Gram', 'WEIGHT', 0, 0.001, 3, 'g', 1, 'admin', SYSDATETIME()
WHERE  NOT EXISTS (SELECT 1 FROM dbo.MD_Uom WHERE UOMCode = 'G');
PRINT CONCAT(N'§1 MD_Uom 추가: ', @@ROWCOUNT, N' 건');

