INSERT INTO dbo.MD_Bom
       (BOMID, ParentItemNo, CompItemNo, BOMLevel, QtyPer, UOM, ScrapPct, VersionID, Position, Note, ActiveFlag, CreatedBy, CreatedTS)
SELECT  b.BOMID, b.ParentItemNo, b.CompItemNo, 1, b.QtyPer, b.UOM, 0, b.VersionID, b.Position, NULL, 1, 'admin', SYSDATETIME()
FROM    b
WHERE   NOT EXISTS (SELECT 1 FROM dbo.MD_Bom t WHERE t.BOMID = b.BOMID);
PRINT CONCAT(N'§4 MD_Bom 추가: ', @@ROWCOUNT, N' 건');

COMMIT;
GO

-- 확인
SELECT (SELECT COUNT(*) FROM dbo.MD_Uom)                              AS Uom,
       (SELECT COUNT(*) FROM dbo.MD_Item)                             AS Items,
       (SELECT COUNT(*) FROM dbo.MD_BomVersion)                       AS Versions,
       (SELECT COUNT(*) FROM dbo.MD_Bom)                              AS BomLines;

-- 부품명이 안 풀리는 라인 (0건이어야 정상)
SELECT b.VersionID, b.ParentItemNo, b.CompItemNo
FROM   dbo.MD_Bom b
WHERE  NOT EXISTS (SELECT 1 FROM dbo.MD_Item i WHERE i.ItemNo = b.CompItemNo)
ORDER  BY b.VersionID, b.Position;

-- 루트별 구성품 수
SELECT TOP 10 v.RootItemNo, COUNT(*) AS 구성품수
FROM   dbo.MD_BomVersion v JOIN dbo.MD_Bom b ON b.VersionID = v.VersionID
GROUP  BY v.RootItemNo ORDER BY 구성품수 DESC;
